import {games as classics} from './games/classics.js';
import {games as modern} from './games/modern.js';
import {games as logic} from './games/logic.js';
import {clone,button} from './games/core.js';
const games=[...classics,...modern,...logic],byId=Object.fromEntries(games.map(g=>[g.id,g]));
const app=document.querySelector('#app'),VERSION='1.1.0',KEY='pocket-puzzle-v1';
let storageOK=true,saves={},recent=[],bestScores={},current=null,paused=false,confirmAction=null,notice='',rulesState={},lastTick=performance.now();
const sessionId=crypto.randomUUID();
const testMode=navigator.webdriver||location.hostname==='localhost'||location.hostname==='127.0.0.1'||new URLSearchParams(location.search).get('test')==='1';
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{storageOK=false;return fallback;}}
const stored=read(KEY,{});if((stored.schema===1||stored.version==='1.0.0')&&stored.saves&&typeof stored.saves==='object'){saves=stored.saves;recent=Array.isArray(stored.recent)?stored.recent.filter(x=>byId[x]):[];}
if(stored.bestScores&&typeof stored.bestScores==='object')bestScores=stored.bestScores;
let events=read('pocket-local-events',[]);if(!Array.isArray(events))events=[];
function event(type,extra={}){if(testMode)return;events.push({version:VERSION,event:type,session_id:sessionId,game_id:current,run_id:current?saves[current]?.runId:null,at:new Date().toISOString(),...extra});events=events.slice(-500);try{localStorage.setItem('pocket-local-events',JSON.stringify(events));}catch{}}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({schema:1,version:VERSION,saves,recent,bestScores}));}catch{storageOK=false;}}
function flushTime(){const now=performance.now();if(current&&!paused&&!confirmAction&&!document.hidden){let s=saves[current];if(s&&!s.finished)s.activeMs+=Math.min(now-lastTick,15000);}lastTick=now;}
function duration(ms){let n=Math.floor(ms/1000);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function fresh(g){const state=g.create();return {runId:crypto.randomUUID(),state,initial:clone(state),history:[],moves:0,activeMs:0,first:false,finished:false,hints:0};}
function validSave(s){return s&&s.state&&s.initial&&Array.isArray(s.history)&&Number.isFinite(s.moves)&&Number.isFinite(s.activeMs);}
function openGame(id,route=true){flushTime();if(current&&current!==id)event('game_switch',{to_game:id,active_ms:Math.round(saves[current]?.activeMs||0)});current=id;paused=false;if(!validSave(saves[id]))saves[id]=fresh(byId[id]);else event('resume',{moves:saves[id].moves});recent=[id,...recent.filter(x=>x!==id)].slice(0,8);persist();render(true);if(route)history.pushState({game:id},'',`#${id}`);window.scrollTo?.({top:0,behavior:'instant'});}
function brand(){return `<a class="brand" href="#" aria-label="Pocket Puzzle Club home"><img src="./favicon.svg" alt="" width="38" height="38"><span>Pocket Puzzle <em>Club</em></span></a>`;}
const colors=['sage','sand','blue','rose','mint','gold','lavender','peach'];
function preview(g){const state=validSave(saves[g.id])?saves[g.id].state:g.create();return `<div class="preview-inner" aria-hidden="true" inert>${g.view(state).replaceAll('<button','<span').replaceAll('</button>','</span>').replace(/data-action="[^"]*"/g,'').replace(/data-value="[^"]*"/g,'')}</div>`;}
function home(){return `<header class="site-header">${brand()}<span class="header-note">A little time, well spent.</span><span class="private-pill">Preview</span></header><main class="home"><div class="home-heading"><div><p class="eyebrow">MAKE YOURSELF AT HOME</p><h1>What feels good today?</h1><p class="intro">Old favourites. New little challenges. Your pace.</p></div><div class="edition"><span>08</span><small>games to<br>make time for</small></div></div>${recent.length?`<section class="continue-strip"><span class="continue-dot"></span><div><small>PICK UP WHERE YOU LEFT OFF</small><strong>${byId[recent[0]].title}</strong></div>${button(saves[recent[0]]?.finished?'View round ↗':'Continue playing →','open',recent[0],'primary')}</section>`:''}<section class="game-catalog" aria-label="Choose a puzzle">${games.map((g,i)=>`<button class="game-card" data-action="open" data-value="${g.id}"><div class="game-preview ${colors[i]}">${preview(g)}<span class="play-badge">Play ↗</span></div><div class="game-card-copy"><div><h2>${g.title}</h2><p>${g.tag}</p></div><span class="card-arrow">↗</span></div></button>`).join('')}</section><footer><span>Made for a quiet moment.</span><span>No accounts. No ads. Progress stays on this device.</span></footer>${!storageOK?'<p class="storage-warning">Browser storage is unavailable. Progress may be lost when this tab closes.</p>':''}</main>`;}
function play(){const g=byId[current],r=saves[current],won=g.won(r.state),ended=g.ended?.(r.state);return `<header class="site-header">${brand()}${button('← All games','home','','back-home')}<span class="private-pill">Preview</span></header><main class="play-layout"><aside class="game-sidebar"><p class="eyebrow">YOUR LITTLE BREAK</p><h1>${g.title}</h1><p class="game-subtitle">${g.subtitle}</p><details class="rules" ${(rulesState[current]??matchMedia('(min-width:801px)').matches)?'open':''}><summary>How to play</summary><p>${g.rules}</p></details><p class="local-note"><span>◉</span> Saved on this device<br><small>Sound off · No timer pressure</small></p></aside><section class="play-surface ${current}" aria-label="${g.title} game"><div class="game-toolbar"><div class="run-stats"><span><b>${r.moves}</b> moves</span><span id="timer">${duration(r.activeMs)}</span></div><div class="toolbar-buttons">${button(paused?'Resume':'Pause','pause','','quiet')}${button('New game','new','','quiet')}</div></div><div class="board-wrap ${won?'is-won':''}">${paused?`<div class="pause-screen"><span>Ⅱ</span><h2>Take your time</h2><p>Your puzzle will be right here.</p>${button('Keep playing','pause','','primary')}</div>`:g.view(current==='blocks'?{...r.state,best:Number(bestScores.blocks)||0}:r.state)}</div><div class="game-feedback" role="status" aria-live="polite">${won?'<strong>Beautifully done. Puzzle complete!</strong>':r.state.message||'A little focus. One move at a time.'}</div><div class="game-controls">${button('↶ Undo','undo','','',r.history.length&&!paused?'':'disabled')}${button('✦ Hint','hint','','',paused||won?'disabled':'')}${button('↻ Restart','restart','','',paused?'disabled':'')}</div>${won?`<div class="win-note">${r.moves} moves · ${r.hints} hints · ${duration(r.activeMs)} active play ${button('Another puzzle →','new','','primary')}</div>`:''}${ended?`<div class="win-note"><strong>Round complete · ${r.state.score} points</strong><p>No remaining blocks fit. Undo to try another move, or start fresh.</p>${button('Play again →','new','','primary')}</div>`:''}</section><nav class="game-switcher" aria-label="Other games">${games.map(x=>button(x.title,'open',x.id,x.id===current?'active':'')).join('')}</nav></main>${!storageOK?'<p class="storage-warning">Saving is unavailable in this browser. Keep this tab open to retain your puzzle.</p>':''}`;}
function render(routeChange=false){const focused=routeChange?null:document.activeElement?.dataset;app.innerHTML=(current?play():home())+(confirmAction?`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="dialog-title" class="confirm-dialog"><h2 id="dialog-title">${confirmAction==='new'?'A fresh start?':'Try this puzzle again?'}</h2><p>${confirmAction==='new'?'Your current round will be replaced with a new puzzle.':'The original board will return and your moves will reset.'}</p><div>${button('Keep playing','cancel','','quiet')}${button(confirmAction==='new'?'New game':'Restart','confirm','','primary')}</div></section></div>`:'');if(confirmAction)app.querySelector('[data-action="cancel"]').focus();else if(focused?.action){const el=[...app.querySelectorAll('[data-action]')].find(e=>e.dataset.action===focused.action&&e.dataset.value===focused.value);el?.focus({preventScroll:true});}}
function handle(action,value){if(confirmAction&&action!=='confirm'&&action!=='cancel')return;if(action==='cancel'){confirmAction=null;lastTick=performance.now();render();return;}if(action==='home'){flushTime();if(current)event('active_foreground_duration',{active_ms:Math.round(saves[current].activeMs)});current=null;paused=false;persist();render(true);if(value!=='history')history.pushState({},'','#');window.scrollTo?.({top:0,behavior:'instant'});return;}if(action==='open'&&byId[value]){openGame(value);return;}if(!current)return;const g=byId[current],r=saves[current];if(action==='new'||action==='restart'){flushTime();confirmAction=action;render();return;}if(action==='confirm'){if(!r.finished&&!r.outcomeRecorded)event('run_outcome',{outcome:'abandoned',reason:confirmAction,moves:r.moves});saves[current]=confirmAction==='new'?fresh(g):{...fresh(g),state:clone(r.initial),initial:clone(r.initial)};confirmAction=null;paused=false;lastTick=performance.now();persist();render(true);return;}if(action==='pause'){flushTime();paused=!paused;if(!paused)lastTick=performance.now();render();return;}if(paused)return;if(action==='undo'){if(r.history.length){flushTime();let old=r.history.pop();r.state=old.state;r.moves=old.moves;r.finished=false;event('undo');persist();render();}return;}if(g.won(r.state))return;flushTime();let before={state:clone(r.state),moves:r.moves},changed=g.action(r.state,action,value);if(action==='hint'){r.hints++;event('hint');}if(changed){if(current==='blocks'){bestScores.blocks=Math.max(Number(bestScores.blocks)||0,r.state.score);}r.history.push(before);if(r.history.length>120)r.history.shift();if(action!=='hint'){r.moves++;if(!r.first){r.first=true;event('first_valid_move');}}if(g.won(r.state)||g.ended?.(r.state)){r.finished=true;if(!r.outcomeRecorded){r.outcomeRecorded=true;event('run_outcome',{outcome:g.won(r.state)?'won':'no_moves',moves:r.moves,hints:r.hints,active_ms:Math.round(r.activeMs)});}}}persist();render();}
app.addEventListener('toggle',e=>{if(current&&e.target.matches?.('.rules'))rulesState[current]=e.target.open;},true);
app.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target&&!target.disabled){try{handle(target.dataset.action,target.dataset.value);}catch(err){event('error',{category:'interaction'});const status=app.querySelector('.game-feedback');if(status)status.textContent='That move could not be completed. Restart this puzzle if it keeps happening.';console.error(err);}}if(e.target.closest('.brand')){e.preventDefault();handle('home');}});
document.addEventListener('keydown',e=>{if(confirmAction&&e.key==='Tab'){const choices=[...app.querySelectorAll('.confirm-dialog button')],ix=choices.indexOf(document.activeElement);e.preventDefault();choices[(ix+(e.shiftKey?-1:1)+choices.length)%choices.length]?.focus();return;}if(e.key==='Escape'){if(confirmAction){handle('cancel');}else if(current)handle('pause');}if(current==='sliding'&&!paused&&!confirmAction&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const z=saves[current].state.cells.indexOf(0),d={ArrowUp:-4,ArrowDown:4,ArrowLeft:-1,ArrowRight:1}[e.key],i=z+d;if(i>=0&&i<16)handle('tile',i);}
if(current==='sudoku'&&!paused&&!confirmAction&&['Backspace','Delete'].includes(e.key)){e.preventDefault();handle('number',0);}
if(current==='sudoku'&&!paused&&!confirmAction&&/^[0-9]$/.test(e.key)){e.preventDefault();handle('number',e.key);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){flushTime();if(current)event('active_foreground_duration',{active_ms:Math.round(saves[current].activeMs)});persist();}lastTick=performance.now();});
window.addEventListener('popstate',()=>{const id=location.hash.slice(1);if(confirmAction)lastTick=performance.now();confirmAction=null;if(byId[id])openGame(id,false);else handle('home','history');});
window.addEventListener('pagehide',()=>{flushTime();persist();});window.addEventListener('error',()=>event('error',{category:'runtime'}));
setInterval(()=>{flushTime();const timer=document.querySelector('#timer');if(timer&&current)timer.textContent=duration(saves[current].activeMs);persist();},1000);
const entryParams=new URLSearchParams(location.search),sourceApp=['dot','email','search','social'].includes(entryParams.get('source'))?entryParams.get('source'):(document.referrer?'referral':'direct');event('page_entry',{source_category:sourceApp,campaign:entryParams.get('campaign')==='private-preview'?'private-preview':null});if(byId[location.hash?.slice(1)])openGame(location.hash.slice(1),false);else render();
